sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hs-home-container {

  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;

}
 
.hs-hero-banner {
  background: 
    url('https://static.vecteezy.com/system/resources/thumbnails/022/263/381/small_2x/blank-poster-wall-frame-mock-up-in-modern-scandinavian-style-living-room-interior-modern-living-room-interior-background-sofa-and-plant-on-table-3d-rendering-generative-ai-photo.jpg') center/cover no-repeat;
  color: darkred;
  text-align: center;
  padding: 100px 20px;
  border-radius: 16px;
}
 
 
.hs-hero-banner h1 {
  font-size: 32px;
  margin-bottom: 10px;
}
 
.hs-hero-banner p {
  font-size: 18px;
}

.hs-action-card {

  background: #ffffff;

  margin: -40px auto 30px auto;

  padding: 30px;

  max-width: 500px;

  border-radius: 12px;

  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);

  text-align: center;

  position: relative;

  z-index: 10;

}
 
.hs-action-card .card-content i {

  font-size: 40px;

  color: #cc0000;

  margin-bottom: 10px;

}
 
.hs-action-card .card-content h2 {

  margin: 10px 0;

  color: #b30000;

}
 
.hs-action-card .card-content p {

  color: #555;

  margin-bottom: 20px;

}
 
.hs-action-card button {

  background-color: #cc0000;

  color: #fff;

  border: none;

  padding: 12px 25px;

  border-radius: 8px;

  cursor: pointer;

  font-size: 16px;

  transition: background-color 0.3s ease;

}
 
.hs-action-card button:hover {

  background-color: #990000;

}
 
.hs-process-tracker {

  display: flex;

  justify-content: center;

  align-items: center;

  margin-top: 40px;

  flex-wrap: wrap;

}
 
.hs-process-tracker .step {

  display: flex;

  flex-direction: column;

  align-items: center;

  text-align: center;

}
 
.hs-process-tracker .step i {

  font-size: 28px;

  color: #cc0000;

  margin-bottom: 5px;

}
 
.hs-process-tracker .step p {

  font-size: 14px;

  color: #333;

}
 
.hs-process-tracker .tracker-line {

  width: 30px;

  height: 2px;

  background-color: #cc0000;

  margin: 0 10px;

}
